#include "ES28.h"

// D4 is PB10 on the Nucleo header.
#define GPIOBEN  (1U << 1)        // RCC->IOPENR bit 1 = GPIOB clock
#define LED_PIN  (1U << 10)       // PB10

int main(void) {
    RCC->IOPENR  |= GPIOBEN;
    GPIOB->MODER |= (1U << 20);   // PB10: MODER bits 20,21
    GPIOB->MODER &= ~(1U << 21);  // -> output (01)

    while (1) {
        GPIOB->ODR |= LED_PIN;
        delay_ms(500);
        GPIOB->ODR &= ~LED_PIN;
        delay_ms(500);
    }
    return 0;
}

#include "ES28.h"

#define LED_PIN  (1U << 5)        // PA5, on-board LED
#define BTN_PIN  (1U << 13)       // PC13, on-board B1 button (active-low)

int main(void) {
    RCC->IOPENR  |= (1U << 0);    // GPIOA clock
    RCC->IOPENR  |= (1U << 2);    // GPIOC clock

    GPIOA->MODER |= (1U << 10);   // PA5 output
    GPIOA->MODER &= ~(1U << 11);
    GPIOC->MODER &= ~(3U << 26);  // PC13 input (B1 has an external pull-up)

    while (1) {
        if ((GPIOC->IDR & BTN_PIN) == 0)  // pressed reads 0
            GPIOA->ODR |= LED_PIN;        // LED on
        else
            GPIOA->ODR &= ~LED_PIN;       // LED off
    }
    return 0;
}

#include "ES28.h"
#define GPIOAEN (1U<<0)
#define GPIOBEN (1U<<1)
#define LED_PIN    (1U<<5)   // PA5 / D13
#define BUTTON_PIN (1U<<4)   // PB4 / D5
int main(void) {
    unsigned buttonAlreadyPressed = 0, buttonPushed;
    RCC->IOPENR |= (GPIOAEN | GPIOBEN);
    GPIOA->MODER |= (1U<<10);  GPIOA->MODER &= ~(1U<<11);   // PA5 output
    GPIOB->MODER &= ~(1U<<8) & ~(1U<<9);                    // PB4 input
    GPIOB->PUPDR |= (1U<<8);   GPIOB->PUPDR &= ~(1U<<9);    // PB4 pull-up
    while (1) {
        buttonPushed = ((GPIOB->IDR & BUTTON_PIN) == 0);
        if (!buttonAlreadyPressed) {
            if (buttonPushed) { GPIOA->ODR ^= LED_PIN; buttonAlreadyPressed = 1; }
        } else {
            if (!buttonPushed) buttonAlreadyPressed = 0;
        }
    }
    return 0;
}

