#include "ES28.h"
#include <stdio.h>

// What uart2_init() does inside, written out: pins, clock, baud rate, enable.
// Step through it and watch GPIOA->AFR[0], RCC->APBENR1, USART2->BRR and
// USART2->CR1 change in the register panel.

#define SYS_FREQ   12000000U      // 12 MHz HSI
#define BAUD_RATE  9600U

void uart2_init(void) {
    // Step 1: GPIOA clock, or every GPIOA write below is discarded.
    RCC->IOPENR |= RCC_IOPENR_GPIOAEN;

    // Step 2: PA2 (TX) and PA3 (RX) to alternate-function mode.
    GPIOA->MODER &= ~GPIO_MODER_MODE2_Msk;
    GPIOA->MODER |= (GPIO_ALTERNATE << GPIO_MODER_MODE2_Pos);
    GPIOA->MODER &= ~GPIO_MODER_MODE3_Msk;
    GPIOA->MODER |= (GPIO_ALTERNATE << GPIO_MODER_MODE3_Pos);

    // Step 3: select AF1 (USART2) for both pins in AFRL.
    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL2_Msk;
    GPIOA->AFR[0] |= (GPIO_AF1 << GPIO_AFRL_AFSEL2_Pos);
    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL3_Msk;
    GPIOA->AFR[0] |= (GPIO_AF1 << GPIO_AFRL_AFSEL3_Pos);

    // Step 4: USART2 clock, on APB1.
    RCC->APBENR1 |= RCC_APBENR1_USART2EN;

    // Step 5: baud rate, BEFORE enabling the USART.
    USART2->BRR = (SYS_FREQ + (BAUD_RATE / 2U)) / BAUD_RATE;   // 1250

    // Step 6: transmitter and receiver first, then the USART itself.
    USART2->CR1 = USART_CR1_RE | USART_CR1_TE;
    USART2->CR1 |= USART_CR1_UE;
}

// printf reaches the terminal through this: __io_putchar is a weak symbol in
// the ARM C library, and defining it here overrides the library's version.
int __io_putchar(int ch) {
    while (!(USART2->ISR & USART_ISR_TXE_TXFNF)) {}
    USART2->TDR = (ch & 0xFF);
    return ch;
}

int main(void) {
    uart2_init();

    printf("Driver written by hand, printf routed through __io_putchar\r\n");
    printf("MODER = 0x%08lx\r\n", GPIOA->MODER);

    while (1) {
        delay_ms(1000);
    }
    return 0;
}

