#include <stdio.h>
#include "ES28.h"
#include "uart.h"

/* ADCPot.c, filled in. A0 is PA0, and PA0 is ADC channel 0 -- three naming
 * schemes that happen to agree here and do not agree for A3 (PB1, channel 18).
 */

void     pa0_adc_init(void);
void     start_conversion(void);
uint16_t adc_read(void);

int main(void) {
    uint16_t sensor_value;
    uart2_init();

    printf("\r\nHello from STM32C0!\r\n");
    printf("Single conversion ADC test\r\n");

    pa0_adc_init();

    while (1) {
        start_conversion();
        sensor_value = adc_read();
        printf("Sensor value: %d\r\n", sensor_value);
        delay_ms(1000);
    }
    return 0;
}

void pa0_adc_init(void) {
    // TODO 1 -- PA0 as an analog input: port clock, then the mode field
    RCC->IOPENR  |= RCC_IOPENR_GPIOAEN;
    GPIOA->MODER &= ~GPIO_MODER_MODE0_Msk;
    GPIOA->MODER |= (GPIO_ANALOG << GPIO_MODER_MODE0_Pos);

    // TODO 2 -- the ADC's own clock
    RCC->APBENR2 |= RCC_APBENR2_ADCEN;

    // TODO 3 -- channel 0, with a plain = so nothing else stays selected
    ADC1->CHSELR = ADC_CHSELR_CHSEL0;

    // Enable the ADC module
    ADC1->ISR = ADC_ISR_ADRDY;
    ADC1->CR |= ADC_CR_ADEN;
}

void start_conversion(void) {
    // TODO 4 -- wait for the converter to report itself ready
    while (!(ADC1->ISR & ADC_ISR_ADRDY));

    ADC1->CR |= ADC_CR_ADSTART;
}

uint16_t adc_read(void) {
    // TODO 5 -- wait for the conversion to finish
    while (!(ADC1->ISR & ADC_ISR_EOC));

    return (uint16_t) ADC1->DR;
}

#include <stdio.h>
#include "ES28.h"
#define LED (1U<<5)        // blinking the on-board LED
#define PSC_FACTOR 12000   // 12 MHz/12000 = 1 kHz
#define ARR_FACTOR 500     // 1 kHz/500 = 2 Hz

void tim14_500ms_interrupt_init();
volatile int timerElapsed;             // TODO 4a: the shared flag, volatile

int main(void) {
    RCC->IOPENR |= RCC_IOPENR_GPIOAEN;
    GPIOA->MODER &= ~GPIO_MODER_MODE5_Msk;
    GPIOA->MODER |= (GPIO_OUTPUT << GPIO_MODER_MODE5_Pos);
    GPIOA->ODR &= ~(LED);              // Start LED as off
    timerElapsed = 0;                  // TODO 4b: initialize flag
    tim14_500ms_interrupt_init();

    while (1) {
        if (timerElapsed) {            // TODO 4c: consume the flag
            timerElapsed = 0;          //   clear flag
            GPIOA->ODR ^= LED;         //   toggle LED
        }
    }
    return 0;
}

void tim14_500ms_interrupt_init() {
    __disable_irq();
    RCC->APBENR2 |= RCC_APBENR2_TIM14EN;
    TIM14->PSC = PSC_FACTOR - 1;
    TIM14->ARR = ARR_FACTOR - 1;
    TIM14->CNT = 0;
    TIM14->DIER |= TIM_DIER_UIE;       // TODO 1: enable update interrupt
    NVIC_EnableIRQ(TIM14_IRQn);        // TODO 2: enable in NVIC
    TIM14->CR1 |= TIM_CR1_CEN;
    __enable_irq();
}

void TIM14_IRQHandler(void) {          // TODO 3: exact vector-table name
    __disable_irq();
    TIM14->SR = ~TIM_SR_UIF;           //   clear UIF -- the Part 5 idiom
    timerElapsed = 1;                  //   set global flag
    __enable_irq();
}

#include <stdio.h>
#include "ES28.h"
#include "uart.h"

#define MAXCOUNT  100

void pb4_exti_init(void);

volatile int buttonPushed;              // TODO 3a


int main(void) {
    int counter = 0;

    uart2_init();
    printf("Hex \tDecimal\r\n");

    pb4_exti_init();

    buttonPushed = 0;                   // TODO 3b

    while(1) {
        printf("%x\t%d\r\n", counter, counter);
        delay_ms(1000);

        // TODO 3c -- one chain, so a press does not reset then increment.
        if (buttonPushed) {
            counter = 0; buttonPushed = 0;
        } else if (counter == MAXCOUNT) {
            counter = 0;
        } else {
            counter++;
        }
    }
    return 0;
}

void pb4_exti_init(void) {
    // Disable global interrupts while the EXTI is half-configured
    __disable_irq();                        // given: no interrupts during setup

    // Enable clock access to GPIOB, then PB4 as an input with a pull-up.
    // This is the Day 3 configuration, unchanged.
    RCC->IOPENR |= RCC_IOPENR_GPIOBEN;      // given: the Day 3 pin configuration
    GPIOB->MODER &= ~GPIO_MODER_MODE4_Msk;
    GPIOB->MODER |= (GPIO_INPUT << GPIO_MODER_MODE4_Pos);
    GPIOB->PUPDR &= ~GPIO_PUPDR_PUPD4_Msk;
    GPIOB->PUPDR |= (GPIO_PULLUP << GPIO_PUPDR_PUPD4_Pos);

    EXTI->EXTICR[1] &= ~EXTI_EXTICR2_EXTI4_Msk;   // TODO 1a: which port
    EXTI->EXTICR[1] |= (EXTI_PB << EXTI_EXTICR2_EXTI4_Pos);
    EXTI->FTSR1 |= EXTI_FTSR1_FT4;                // TODO 1b: which edge
    EXTI->IMR1  |= EXTI_IMR1_IM4;                 // TODO 1c: unmask
    NVIC_EnableIRQ(EXTI4_15_IRQn);                // TODO 1d: the NVIC

    // Setup done: allow interrupts again
    __enable_irq();                         // given: setup done, interrupts on
}

// TODO 2 -- the handler, named exactly as the startup file has it.
void EXTI4_15_IRQHandler(void){
    __disable_irq();

    if (EXTI->FPR1 & EXTI_FPR1_FPIF4) {   // a falling edge happened on EXTI4
        EXTI->FPR1 = EXTI_FPR1_FPIF4;     // clear the pending flag: write 1
        buttonPushed = 1;
    }
    __enable_irq();
}
